import hashlib
import hmac
import os
import time
import secrets
import sqlite3
from contextlib import contextmanager

# Secure password hashing with PBKDF2
PBKDF2_ITERATIONS = 600000
SALT_LENGTH = 32
DB_PATH = ':memory:'

def _init_db(conn):
    conn.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        display_name TEXT NOT NULL,
        password_hash BLOB NOT NULL,
        salt BLOB NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        is_active INTEGER NOT NULL DEFAULT 1,
        created_at REAL NOT NULL
    )''')
    conn.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        created_at REAL NOT NULL,
        expires_at REAL NOT NULL,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    conn.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER,
        action TEXT NOT NULL,
        detail TEXT,
        timestamp REAL NOT NULL
    )''')
    conn.commit()

def _hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(SALT_LENGTH)
    pw_bytes = password.encode('utf-8')
    dk = hashlib.pbkdf2_hmac('sha256', pw_bytes, salt, PBKDF2_ITERATIONS)
    return dk, salt

def _validate_username(username):
    """Validate username contains only allowed characters.
    Rejects any non-ASCII to prevent Unicode confusion attacks.
    Only allows: a-z, 0-9, underscore, hyphen, period."""
    if not username:
        return None
    # Strict ASCII-only validation
    allowed = set('abcdefghijklmnopqrstuvwxyz0123456789_-.')
    lower_username = username.lower()
    if not all(c in allowed for c in lower_username):
        return None
    if len(lower_username) > 64:
        return None
    if lower_username.startswith('.') or lower_username.endswith('.'):
        return None
    if '..' in lower_username:
        return None
    return lower_username

def _constant_time_username_compare(a, b):
    """Compare usernames in constant time to prevent timing oracles.
    Uses XOR accumulation over fixed-length padded buffers."""
    # Pad both to max length to prevent length-based timing leaks
    max_len = 64
    a_padded = a.ljust(max_len, '\x00').encode('ascii')
    b_padded = b.ljust(max_len, '\x00').encode('ascii')
    return hmac.compare_digest(a_padded, b_padded)

def register_user(conn, username, password, display_name=None):
    """Register a new user with validated username."""
    if not username or not password:
        return {'error': 'Username and password required'}
    if len(password) < 8:
        return {'error': 'Password must be at least 8 characters'}

    # Validate and normalize username (ASCII-only, lowercase)
    norm_username = _validate_username(username)
    if norm_username is None:
        return {'error': 'Invalid username. Use only a-z, 0-9, underscore, hyphen, period.'}

    if display_name is None:
        display_name = username
    # Sanitize display_name length
    display_name = display_name[:128]

    password_hash, salt = _hash_password(password)

    try:
        conn.execute(
            'INSERT INTO users (username, display_name, password_hash, salt, role, created_at) VALUES (?, ?, ?, ?, ?, ?)',
            (norm_username, display_name, password_hash, salt, 'user', time.time())
        )
        conn.commit()
        _audit(conn, None, 'register', f'User registered: {norm_username}')
        return {'success': True, 'username': norm_username}
    except sqlite3.IntegrityError:
        return {'error': 'Username already exists'}

def authenticate(conn, username, password):
    """Authenticate user and create session."""
    if not username or not password:
        return {'error': 'Credentials required'}

    # Validate and normalize for lookup
    norm_username = _validate_username(username)
    if norm_username is None:
        # Still do dummy hash to prevent timing oracle
        _hash_password(password, os.urandom(SALT_LENGTH))
        return {'error': 'Invalid credentials'}

    row = conn.execute(
        'SELECT id, password_hash, salt, role, is_active FROM users WHERE username = ?',
        (norm_username,)
    ).fetchone()

    if row is None:
        # Perform dummy hash to prevent timing oracle
        _hash_password(password, os.urandom(SALT_LENGTH))
        return {'error': 'Invalid credentials'}

    user_id, stored_hash, salt, role, is_active = row

    if not is_active:
        return {'error': 'Account disabled'}

    computed_hash, _ = _hash_password(password, salt)

    if not hmac.compare_digest(computed_hash, stored_hash):
        _audit(conn, user_id, 'failed_login', f'Failed login for {norm_username}')
        return {'error': 'Invalid credentials'}

    # Create session
    token = secrets.token_urlsafe(32)
    expires = time.time() + 3600  # 1 hour
    conn.execute(
        'INSERT INTO sessions (token, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)',
        (token, user_id, time.time(), expires)
    )
    conn.commit()
    _audit(conn, user_id, 'login', f'Successful login for {norm_username}')
    return {'success': True, 'token': token, 'role': role}

def get_user_profile(conn, token, target_username):
    """Get user profile. Users can view their own; admins can view any."""
    session = _validate_session(conn, token)
    if session is None:
        return {'error': 'Invalid or expired session'}

    user_id, role = session

    # Validate target
    norm_target = _validate_username(target_username)
    if norm_target is None:
        return {'error': 'Invalid username'}

    # Authorization check
    if role != 'admin':
        # Non-admins can only view their own profile
        own_username = conn.execute(
            'SELECT username FROM users WHERE id = ?', (user_id,)
        ).fetchone()
        if own_username is None or not _constant_time_username_compare(own_username[0], norm_target):
            return {'error': 'Access denied'}

    row = conn.execute(
        'SELECT username, display_name, role, created_at FROM users WHERE username = ?',
        (norm_target,)
    ).fetchone()

    if row is None:
        return {'error': 'User not found'}

    return {'username': row[0], 'display_name': row[1], 'role': row[2], 'created_at': row[3]}

def change_role(conn, token, target_username, new_role):
    """Admin-only: change a user's role."""
    session = _validate_session(conn, token)
    if session is None:
        return {'error': 'Invalid or expired session'}

    user_id, role = session
    if role != 'admin':
        return {'error': 'Admin access required'}

    if new_role not in ('user', 'moderator', 'admin'):
        return {'error': 'Invalid role'}

    norm_target = _validate_username(target_username)
    if norm_target is None:
        return {'error': 'Invalid username'}

    result = conn.execute(
        'UPDATE users SET role = ? WHERE username = ?',
        (new_role, norm_target)
    )
    conn.commit()

    if result.rowcount == 0:
        return {'error': 'User not found'}

    _audit(conn, user_id, 'change_role', f'Changed {norm_target} to {new_role}')
    return {'success': True}

def _validate_session(conn, token):
    """Validate session token and return (user_id, role) or None."""
    if not token:
        return None
    row = conn.execute(
        '''SELECT s.user_id, u.role FROM sessions s
           JOIN users u ON s.user_id = u.id
           WHERE s.token = ? AND s.expires_at > ? AND u.is_active = 1''',
        (token, time.time())
    ).fetchone()
    return row

def _audit(conn, user_id, action, detail):
    conn.execute(
        'INSERT INTO audit_log (user_id, action, detail, timestamp) VALUES (?, ?, ?, ?)',
        (user_id, action, detail, time.time())
    )
    conn.commit()

def reset_password(conn, token, target_username, new_password):
    """Admin can reset any user's password. Users can reset their own."""
    session = _validate_session(conn, token)
    if session is None:
        return {'error': 'Invalid or expired session'}

    user_id, role = session

    norm_target = _validate_username(target_username)
    if norm_target is None:
        return {'error': 'Invalid username'}

    if role != 'admin':
        own_username = conn.execute(
            'SELECT username FROM users WHERE id = ?', (user_id,)
        ).fetchone()
        if own_username is None or not _constant_time_username_compare(own_username[0], norm_target):
            return {'error': 'Access denied'}

    if len(new_password) < 8:
        return {'error': 'Password must be at least 8 characters'}

    password_hash, salt = _hash_password(new_password)
    result = conn.execute(
        'UPDATE users SET password_hash = ?, salt = ? WHERE username = ?',
        (password_hash, salt, norm_target)
    )
    conn.commit()

    if result.rowcount == 0:
        return {'error': 'User not found'}

    _audit(conn, user_id, 'reset_password', f'Password reset for {norm_target}')
    return {'success': True}
